    /// Search coins, profiles, content and trends by text. Returns one page;
    /// [`Client::iter_search`] streams every page.
    ///
    /// `GET /search`
    pub async fn search(
        &self,
        text: &str,
        params: impl Into<Option<SearchParams>>,
    ) -> Result<SearchResultConnection> {
        let params = params.into().unwrap_or_default();
        #[allow(unused_mut)]
        let mut q: Vec<(&str, String)> = Vec::new();
        q.push(("text", text.to_string()));
        if let Some(v) = &params.entity_type {
            q.push(("entityType", v.to_string()));
        }
        if let Some(v) = &params.page_size {
            q.push(("first", v.to_string()));
        }
        if let Some(v) = &params.after {
            q.push(("after", v.to_string()));
        }
        let resp: SearchResponse = self.request("GET", "/search", &q, None).await?;
        Ok(Some(resp).and_then(|x| x.global_search).unwrap_or_default())
    }

    /// Streams every SearchResult across all pages, fetching the next page only as the stream is
