    /// Quote a trade. The result holds the transaction that executes it. Amounts are in the input
    /// token's smallest unit (wei for ETH). Set Referrer to earn the trade referral reward. Nothing
    /// is signed or sent: pass the returned call to your wallet.
    ///
    /// `POST /quote`
    pub async fn quote(&self, req: &QuoteRequest) -> Result<QuoteResponse> {
        #[allow(unused_mut)]
        let mut q: Vec<(&str, String)> = Vec::new();
        let resp: QuoteResponse = self
            .request("POST", "/quote", &q, Some(serde_json::to_value(req)?))
            .await?;
        Ok(resp)
    }

    /// Build the transaction that creates a content coin. The result also holds the coin's
    /// predicted address. Set PlatformReferrer to earn the platform referral share of the coin's
    /// trading fees for its whole life. Nothing is signed or sent.
    ///
    /// `POST /create/content`
    pub async fn create_content_coin(
        &self,
        req: &CreateContentCoinRequest,
    ) -> Result<CreateContentCoinResponse> {
        #[allow(unused_mut)]
        let mut q: Vec<(&str, String)> = Vec::new();
        let resp: CreateContentCoinResponse = self
            .request(
                "POST",
                "/create/content",
                &q,
                Some(serde_json::to_value(req)?),
            )
            .await?;
        Ok(resp)
    }
